def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    high_const = []
    mid_const = []
    for b in prev_bids:
        if b >= 120:
            high_const.append(b)
        elif b >= 60:
            mid_const.append(b)

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    urgent = hp <= 3 or no_water_days >= 2
    pressured = slots <= 1

    david_anchor = 76.0
    if mid_const:
        david_anchor = max(mid_const)

    if urgent:
        bid = min(budget, max(88.0, david_anchor + 2.0))
    elif pressured:
        if hp >= 8 and budget < 350:
            bid = min(budget, 18.0)
        else:
            bid = min(budget, david_anchor + 1.5)
    else:
        if hp >= 8:
            bid = min(budget, 12.0)
        elif hp >= 5:
            bid = min(budget, 28.0)
        else:
            bid = min(budget, 52.0)

    if day >= 8:
        if hp <= 5:
            bid = max(bid, min(budget, david_anchor + 2.0))
        else:
            bid = max(bid, min(budget, 24.0))

    if budget < 100 and not urgent:
        bid = min(bid, budget * 0.45)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

