def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    remaining_days = EPISODE_DAYS - day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    available_water_units = int(day_context['supply'] // WATER_REQ)
    total_competitors_for_water = num_alive_opponents + 1

    current_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        current_bid = DAILY_SALARY * 0.8
    elif remaining_days <= 2 and my_status['hp'] < 6:
        current_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if total_competitors_for_water > available_water_units:
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                current_bid = max(current_bid, highest_prev_bid + 5)
            else:
                current_bid = max(current_bid, DAILY_SALARY * 0.7)
        else:
            current_bid = min(current_bid, highest_prev_bid + 1)
            current_bid = max(current_bid, DAILY_SALARY * 0.4)

            if my_status['hp'] > 6 and current_bid > DAILY_SALARY * 0.6:
                current_bid = DAILY_SALARY * 0.6

    final_bid = min(my_status['budget'], current_bid)
    final_bid = max(final_bid, 1.0)

    return final_bid
